export function seasonAsset(seasonId: string, role: SeasonAssetDef["role"], match: RegExp): SeasonAssetDef | null {
  const list = SEASON_ASSETS[seasonId] ?? []
  for (const a of list) if (a.role === role && match.test(a.name)) return a
  return null
}

export function seasonAssets(seasonId: string, role: SeasonAssetDef["role"]): SeasonAssetDef[] {
  return (SEASON_ASSETS[seasonId] ?? []).filter((a) => a.role === role)
}
